'use strict';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validateCreate(body) {
  const { userId, type, title, message, data, recipientEmail, sendEmail, templateParams } = body;

  if (!userId || typeof userId !== 'string' || !userId.trim())
    return 'userId is required';

  if (type !== undefined && type !== null) {
    if (typeof type !== 'string' || !type.trim())
      return 'type must be a non-empty string when provided';
  }

  // If templateParams is given, title and message can be auto-generated by the template
  const hasTemplateParams = templateParams && typeof templateParams === 'object';
  if (!hasTemplateParams) {
    if (!title || typeof title !== 'string' || !title.trim())
      return 'title is required';
    if (!message || typeof message !== 'string' || !message.trim())
      return 'message is required';
  }

  if (title && title.length > 255)
    return 'title must not exceed 255 characters';

  if (message && message.length > 5000)
    return 'message must not exceed 5000 characters';

  if (data !== undefined && data !== null) {
    if (typeof data !== 'object' || Array.isArray(data))
      return 'data must be a plain object when provided';
  }

  if (recipientEmail !== undefined && recipientEmail !== null) {
    if (typeof recipientEmail !== 'string' || !EMAIL_RE.test(recipientEmail.trim()))
      return 'recipientEmail must be a valid email address';
  }

  if (sendEmail !== undefined && sendEmail !== null) {
    if (typeof sendEmail !== 'boolean')
      return 'sendEmail must be a boolean';
  }

  if (templateParams !== undefined && templateParams !== null) {
    if (typeof templateParams !== 'object' || Array.isArray(templateParams))
      return 'templateParams must be a plain object when provided';
  }

  if (body.cc !== undefined && body.cc !== null) {
    if (typeof body.cc === 'string') {
      if (body.cc.trim() && !EMAIL_RE.test(body.cc.trim())) {
        return 'cc must be a valid email address';
      }
    } else if (Array.isArray(body.cc)) {
      for (const email of body.cc) {
        if (typeof email !== 'string' || !EMAIL_RE.test(email.trim())) {
          return 'cc must contain valid email addresses';
        }
      }
    } else {
      return 'cc must be a valid email address or array of email addresses';
    }
  }

  return null;
}

module.exports = { validateCreate };
